def lc(s: str) -> str:
    w = s.split(' ')[0]
    return s if (w in PROPER or w.isupper()) else s[0].lower() + s[1:]


def _key(st):
    return st['id'].rsplit('-', 2)[-2] + '-' + st['id'].rsplit('-', 1)[-1]


def _blk(i, s):
    return f'Source {LAB[i]}\n{s[0]}\n— {s[1]}'


