def source_templates(key: str, d: dict) -> list:
    src, topic, cmp_, ev, essays = d['src'], d['topic'], d['cmp'], d['ev'], d['essays']
    out = []

    def q1(rng, slot):
        i = rng.randrange(len(src))
        s = src[i]
        lab = rng.choice(LAB)
        m = slot.marks or 3
        if slot.set == 'mock':
            q = rng.choice(MQ['q1']).format(L=lab, T=topic)
        else:
            q = rng.choice([s[2].replace('{S}', f'Source {lab}'), f'Outline three points made in Source {lab} about {topic}.'])
        return dict(stem=f'Source {lab}\n{s[0]}\n— {s[1]}\n\n{q} [{m}]', answer='; '.join(s[3]), type='case', marks=m,
                    minutes=float(3 * m),
                    markingKey='Award 1 mark for each of the following, up to [3]: ' + '; '.join(s[3]) +
                               '. Points must be drawn from the source; accept close paraphrase. Own knowledge is not credited.', gap='G7')
    out.append(T('C3', (1, 3), q1, 'case', 'p1q1', 'p1q1'))

    def q2(rng, slot):
        i = rng.randrange(len(src))
        s = src[i]
        lab = rng.choice(LAB)
        m = slot.marks or (4 if slot.d >= 3 else 3)
        e = s[4]  # a clause starting "explain ..."
        if slot.set == 'mock':
            q = rng.choice(MQ['q2']).format(L=lab, E=e, E2=e[0].upper() + e[1:])
        else:
            q = rng.choice([f'With reference to Source {lab}, {e}', f'Using evidence from Source {lab}, {e}'])
        return dict(stem=f'Source {lab}\n{s[0]}\n— {s[1]}\n\n{q} [{m}]', answer=s[5], type='case', marks=m, minutes=float(3 * m),
                    markingKey=f'{s[5]} 3–4 marks: clear explanation with explicit, relevant reference to the source and accurate use '
                               'of concepts; 1–2 marks: limited explanation, or quotation/description without explanation.', gap='G7')
    out.append(T(('C3', 'C4'), (2, 5), q2, 'case', 'p1q2', 'p1q2'))

    if len(src) >= 2 and cmp_:
        def q3(rng, slot):
            if slot.set != 'mock':
                return None  # one source pair per subtopic: reserved for the mock papers
            focus, sims, diffs = cmp_
            a, b = rng.choice([(0, 1), (2, 3), (1, 2)])
            m = slot.marks or 8
            stem = (f'{_blk(a, src[0])}\n\n{_blk(b, src[1])}\n\n' +
                    rng.choice(MQ['q3']).format(A=LAB[a], B=LAB[b], F=focus) + f' [{m}]')
            key = ('Similarities: ' + '; '.join(sims) + '. Differences: ' + '; '.join(diffs) +
                   '. Award 1 mark per valid, source-referenced point of comparison or contrast (up to 8). If only similarities '
                   'or only differences are addressed, award a maximum of 4 marks. Reward a running comparison above two '
                   'separate descriptions.')
            return dict(stem=stem, answer='Similarities: ' + '; '.join(sims) + '. Differences: ' + '; '.join(diffs) + '.',
                        markingKey=key, type='case', marks=m, minutes=float(2.5 * m), gap='G7')
        out.append(T('C4', (3, 5), q3, 'case', 'p1q3', 'p1q3'))

    if len(src) >= 2 and ev:
        def q4(rng, slot):
            if slot.set != 'mock':
                return None
            claim, pro, con, judge = rng.choice(ev)
            a, b = rng.choice([(0, 1), (0, 3), (1, 2)])
            m = slot.marks or 10
            stem = (f'{_blk(a, src[0])}\n\n{_blk(b, src[1])}\n\n' +
                    rng.choice(MQ['q4']).format(c=lc(claim), C=claim, c2=lc(claim).rstrip('.'), A=LAB[a], B=LAB[b]) + f' [{m}]')
            key = ('Supporting: ' + '; '.join(pro) + '. Challenging: ' + '; '.join(con) + f'. Possible judgement: {judge} ' + Q4_BANDS)
            return dict(stem=stem, answer=judge, markingKey=key, type='long', marks=m, minutes=float(2.5 * m), gap='G5')
        out.append(T('C4', (3, 5), q4, 'long', 'p1q4', 'p1q4'))

    def p2(rng, slot):
        pool = [('E', e) for e in essays] + [('V', e) for e in ev]
        if not pool:
            return None
        kind, e = rng.choice(pool)
        m = slot.marks or 15
        if kind == 'E':
            q, pts, judge = e
            pro, con = pts, []
            stem = rng.choice(ME['E']).format(q=q) if slot.set == 'mock' else q
        else:
            claim, pro, con, judge = e
            if slot.set == 'mock':
                stem = rng.choice(ME['V']).format(c=lc(claim), C=claim, c2=lc(claim).rstrip('.'))
            else:
                stem = rng.choice([f'Examine the view that {lc(claim)} Use relevant key concepts and named examples in your answer.',
                                   f'"{claim}" With reference to specific examples, discuss this statement.'])
        key = ('Indicative content – arguments for: ' + '; '.join(pro) +
               ('. Arguments against: ' + '; '.join(con) if con else '') + f'. Possible judgement: {judge} ' + MARKBAND)
        return dict(stem=f'{stem} [{m}]', answer=judge, markingKey=key, type='long', marks=m, minutes=45.0, gap='G5')
    out.append(T('C4', (3, 5), p2, 'long', 'p2', 'p2'))
    return out


def p3_templates(f: F) -> list:
    out = []
    if not f.cases:
        return out

    def p3q1(rng, slot):
        if slot.set != 'mock':
            return None
        case, what, concept, how = rng.choice(f.cases)
        q = rng.choice([f'With reference to the stimulus, explain one way in which {case} illustrates {concept}.',
                        f'Using evidence from the stimulus, explain how {case} demonstrates {concept}.'])
        return dict(stem=f'Paper 3 – Question 1. Read the stimulus.\n\nStimulus: {what}\n\n{q} [4]', answer=how, type='case', marks=4,
                    minutes=12.0, markingKey=f'{how} 1 mark for identifying a relevant feature from the stimulus; up to 3 further '
                                             'marks for explaining clearly how it links to the concept.', gap='G7')
    out.append(T('C3', (1, 5), p3q1, 'case', 'p3q1', 'p3q1'))

    def p3q2(rng, slot):
        if slot.set != 'mock':
            return None
        case, what, concept, how = rng.choice(f.cases)
        q = rng.choice([f'Using the stimulus and one other example you have studied, analyse how {concept} is shaped by the actors involved in {case}.',
                        f'Analyse the significance of {case} for understanding {concept}, comparing it with a second case study of your own.'])
        return dict(stem=f'Paper 3 – Question 2. Read the stimulus.\n\nStimulus: {what}\n\n{q} [9]', answer=f'{how} A second, contrasting case is analysed alongside the stimulus.',
                    type='long', marks=9, minutes=27.0, markingKey=f'Stimulus: {how} The second case must be specific and explicitly compared. ' + P3Q2_BANDS, gap='G5')
    out.append(T('C3', (1, 5), p3q2, 'long', 'p3q2', 'p3q2'))

    def p3q3(rng, slot):
        if slot.set != 'mock' or not f.evaluate:
            return None
        case, what, concept, how = rng.choice(f.cases)
        claim, pro, con, judge = rng.choice(f.evaluate)
        q = rng.choice([f'"{claim}" With reference to the stimulus and your own knowledge, to what extent do you agree with this statement?',
                        f'Drawing on the stimulus and at least two case studies of your own, evaluate the claim that {lc(claim)}'])
        return dict(stem=f'Paper 3 – Question 3. Read the stimulus.\n\nStimulus: {what}\n\n{q} [15]', answer=judge, type='long', marks=15,
                    minutes=45.0, markingKey='Arguments for: ' + '; '.join(pro) + '. Arguments against: ' + '; '.join(con) +
                    f'. Possible judgement: {judge} The stimulus should be used as evidence, not merely summarised. ' + MARKBAND, gap='G5')
    out.append(T('C4', (1, 5), p3q3, 'long', 'p3q3', 'p3q3'))
    return out


def G(key, topic, terms=(), facts=(), why=(), contrast=(), misc=(), cases=(), src=(), cmp=None, ev=(), essays=(),
      apply=(), extended=()):
    R.facts(key, F(terms=list(terms), facts=list(facts), why=list(why), contrast=list(contrast), misc=list(misc),
                   apply=list(apply), cases=list(cases), evaluate=list(ev), extended=list(extended)))
    SRC[key] = dict(topic=topic, src=list(src), cmp=cmp, ev=list(ev), essays=list(essays))


def _fix(fn, fixes):
    def wrapped(rng, slot):
        out = fn(rng, slot)
        if out:
            for a, b in fixes:
                out['stem'] = out['stem'].replace(a, b)
        return out
    return wrapped


def init(subject_id):
    pass


def templates(st):
    key = _key(st)
    out = R.build(st, STYLE)
    f = R.f.get(key)
    if f:
        fixes = []
        for claim in [c[0] for c in f.evaluate] + [c[0] for c in f.misc]:
            if claim.split(' ')[0] not in PROPER:
                fixes.append((' that ' + claim[:30], ' that ' + claim[0].lower() + claim[1:30]))
        if fixes:
            out = [T(t.c, t.d, _fix(t.fn, fixes), t.type, t.style, t.name) for t in out]
        out += p3_templates(f)
    if key in SRC:
        out += source_templates(key, SRC[key])
    return out

