MPI_W = [('nutrition', 3), ('child mortality', 3), ('years of schooling', 3), ('school attendance', 3), ('cooking fuel', 1),
         ('sanitation', 1), ('drinking water', 1), ('electricity', 1), ('housing', 1), ('assets', 1)]
MPI_FRAMES = ['A household survey in {p} finds that the {h} household is deprived in: {L}.',
              'Field researchers in {p} record that the {h} family lacks adequate {L}.',
              'In an MPI training exercise based on {p}, the {h} household shows deprivations in {L}.']
PLACES = ['rural Malawi', 'northern Ghana', 'Bihar, India', 'highland Peru', 'Sindh, Pakistan', 'southern Madagascar', 'Chiapas, Mexico', 'western Nepal']
FAMS = ['Banda', 'Mensah', 'Kumar', 'Quispe', 'Shah', 'Rakoto', 'Hernández', 'Gurung']


@R.add('ch08-st1', 'C3', (2, 5), 'numerical')
def mpi_household(rng, slot):
    k = 2 + min(slot.d, 4)
    ind = rng.sample(MPI_W, k)
    score = sum(w for _, w in ind)
    pct = round(100 * score / 18, 1)
    cls = 'severely multidimensionally poor' if score >= 9 else 'multidimensionally poor' if score >= 6 else \
        'vulnerable to multidimensional poverty' if score >= 4 else 'not poor or vulnerable'
    L = ', '.join(n for n, _ in ind)
    i = rng.randrange(len(PLACES))
    stem = (rng.choice(MPI_FRAMES).format(p=PLACES[i], h=FAMS[i], L=L) +
            ' In the global MPI each health and education indicator carries a weight of 1/6 and each living-standards indicator 1/18. '
            'Calculate the household’s deprivation score and state how it is classified (poor ≥ 1/3; severe ≥ 1/2; vulnerable 1/5 to below 1/3). [3]')
    parts = ' + '.join(f'{w}/18' for _, w in ind)
    return dict(stem=stem, answer=f'Score = {score}/18 ≈ {pct}% → {cls}', type='short', marks=3,
                markingKey=f'M1 weights applied correctly ({parts}); A1 score = {score}/18 ≈ {pct}%; A1 classification: {cls}.')


@R.add('ch08-st1', 'C3', (2, 5), 'numerical')
def mpi_region(rng, slot):
    pop = rng.choice([400, 500, 800, 1000, 1200, 1500, 2000]) * 1000
    hpct = rng.choice([12, 18, 24, 30, 36, 45, 52])
    a = rng.choice([38, 40, 42, 45, 48, 51, 55])
    poor = pop * hpct // 100
    mpi = round(hpct / 100 * a / 100, 3)
    i = rng.randrange(len(PLACES))
    frame = rng.choice([
        f'A province in {PLACES[i]} has a population of {pop:,}. Of these, {poor:,} people are identified as multidimensionally poor, and the average deprivation score among the poor is {a}%.',
        f'Survey data for a district modelled on {PLACES[i]} show {poor:,} multidimensionally poor people out of {pop:,} residents. On average, poor people are deprived in {a}% of weighted indicators.',
        f'An NGO report on {PLACES[i]} states that the incidence of poverty is based on {poor:,} poor people in a population of {pop:,}, with an average intensity of {a}%.'])
    ask = 'Calculate the headcount ratio (H) and the MPI value (H × A), giving the MPI to three decimal places. [3]'
    if slot.d >= 4:
        ask = ('Calculate the headcount ratio (H) and the MPI (H × A) to three decimal places, and explain why two regions with the same H '
               'could have different MPI values. [4]')
    return dict(stem=f'{frame} {ask}', answer=f'H = {hpct}% ({hpct / 100:.2f}); MPI = {hpct / 100:.2f} × {a / 100:.2f} = {mpi:.3f}',
                type='short', marks=4 if slot.d >= 4 else 3,
                markingKey=f'M1 H = {poor:,}/{pop:,} = {hpct / 100:.2f}; M1 MPI = H × A; A1 MPI = {mpi:.3f}.' +
                (' R1 regions with equal H can differ in A, the intensity of deprivation among the poor, so the MPI also reflects how poor the poor are.' if slot.d >= 4 else ''))


