QUOTA_FRAMES = [
    'After an election, the {n}-seat national assembly of {c} contains {w} women.',
    'An IPU-style dataset shows that {w} of the {n} members of the lower house of {c} are women.',
    'A civil society report notes that women hold {w} seats in the {n}-member legislature of {c}.',
]
QCOUNTRIES = ['Country A (a Southern African state)', 'Country B (a Central American state)', 'Country C (a South Asian state)',
              'Country D (a Nordic state)', 'Country E (a Pacific island state)', 'Country F (a West African state)', 'Country G (an Andean state)']


@R.add('ch12-st3', 'C3', (2, 5), 'numerical')
def quota_seats(rng, slot):
    n = rng.choice([60, 80, 100, 120, 150, 200, 240, 300, 350, 400])
    target = rng.choice([30, 33, 40, 50])
    share = rng.choice([8, 12, 15, 18, 21, 24, 27])
    w = n * share // 100
    need = -(-n * target // 100)  # ceil
    extra = need - w
    if extra <= 0:
        return None
    cur = round(100 * w / n, 1)
    c = rng.choice(QCOUNTRIES)
    stem = (rng.choice(QUOTA_FRAMES).format(n=n, c=c, w=w) +
            f' (a) Calculate the percentage of seats held by women. (b) A proposed reserved-seat quota requires that at least {target}% of seats be held by women. '
            'Calculate the minimum number of additional women needed to meet it, assuming the size of the assembly is unchanged.')
    m = 3
    if slot.d >= 4:
        stem += ' (c) Explain one reason why meeting the quota may not achieve substantive representation.'
        m = 5
    stem += f' [{m}]'
    ans = f'(a) {w}/{n} = {cur}%; (b) {target}% of {n} = {n * target / 100:g} → at least {need} women needed, so {extra} more'
    rnd = f' (round up to {need})' if n * target % 100 else ''
    key = f'A1 {cur}%; M1 {target}/100 × {n} = {n * target / 100:g}{rnd}; A1 {extra} additional women.'
    if slot.d >= 4:
        ans += '; (c) e.g. party discipline or exclusion from leadership positions may stop women representatives acting for women’s interests'
        key += ' R2 for a developed reason (party control, tokenism, exclusion from cabinet, descriptive vs substantive representation).'
    return dict(stem=stem, answer=ans, markingKey=key, type='short', marks=m)


